if(inArray(["fr","france","fra"], v), "FR",
if(inArray(["de","deu","germany","allemagne"], v), "DE", if(inArray(["be","bel","belgium","belgique"], v), "BE", if(inArray(["es","spain","espagne"], v), "ES", value)))))

